/** Look up the exact Phosphor SVG path `d` strings for one glyph and weight. */
export function iconPaths(name: IconName, weight: IconWeight = "regular"): readonly string[] {
  return GLYPHS[PHOSPHOR_MAP[name]][weight];
}

export type IconProps = {
  name: IconName;
  /** Regular for chrome, fill for transport and active marks, bold for checks. */
  weight?: IconWeight;
  /** Rendered width and height in px, or a CSS length (e.g. `calc(var(--mq-u) * 26)`). Defaults to 24. */
  size?: number | string;
  className?: string;
  style?: CSSProperties;
  /**
   * Accessible name. Without one the mark is decorative (`aria-hidden="true"`),
   * which is the default beside a visible label or inside a labelled control.
   */
  label?: string;
};

/** Render one Marquee Phosphor glyph on its native 256×256 grid. */
export function Icon({
  name,
  weight = "regular",
  size = 24,
  className,
  style,
  label,
}: IconProps) {
  const paths = iconPaths(name, weight);
  const numericSize = typeof size === "number" ? size : 24;
  const mergedStyle: CSSProperties | undefined =
    typeof size === "string" ? { width: size, height: size, ...style } : style;

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 256 256"
      width={numericSize}
      height={numericSize}
      fill="currentColor"
      className={cx("mq-icon", className)}
      style={mergedStyle}
      {...(label
        ? { role: "img", "aria-label": label }
        : { "aria-hidden": true, focusable: false })}
    >
      {paths.map((d, index) => (
        <path key={index} d={d} />
      ))}
    </svg>
  );
}
